class ProviderProfileScreen extends ConsumerStatefulWidget{const ProviderProfileScreen({super.key});@override ConsumerState<ProviderProfileScreen> createState()=>_ProviderProfileScreenState();}
class _ProviderProfileScreenState extends ConsumerState<ProviderProfileScreen>{final name=TextEditingController(),cnic=TextEditingController(),area=TextEditingController(),city=TextEditingController(text:'Karachi'),years=TextEditingController();double? lat,lng;String? front,back,photo;bool loading=false;String? error;@override void dispose(){name.dispose();cnic.dispose();area.dispose();city.dispose();years.dispose();super.dispose();}@override Widget build(BuildContext c){final l=AppLocalizations.of(c)!;if(ref.watch(authStateProvider).valueOrNull==null)return const SizedBox.shrink();return Scaffold(backgroundColor:AppColors.scaffoldBackground,appBar:AppBar(title:Text(l.providerProfile)),body:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(AppSpacing.xxl),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(l.profileCompletion,style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:AppSpacing.sm),Text(l.profileCompletionHelper,style:Theme.of(c).textTheme.bodyMedium),const SizedBox(height:AppSpacing.xxl),AppTextField(controller:name,label:l.fullName),const SizedBox(height:AppSpacing.md),AppTextField(controller:cnic,label:l.cnicNumber),const SizedBox(height:AppSpacing.md),Row(children:[Expanded(child:OutlinedButton.icon(onPressed:()=>_pick(true),icon:const Icon(Icons.credit_card_rounded),label:Text(l.cnicFront))),const SizedBox(width:AppSpacing.md),Expanded(child:OutlinedButton.icon(onPressed:()=>_pick(false),icon:const Icon(Icons.credit_card_rounded),label:Text(l.cnicBack)))]),const SizedBox(height:AppSpacing.md),AppTextField(controller:area,label:l.area),const SizedBox(height:AppSpacing.md),AppTextField(controller:city,label:l.city),const SizedBox(height:AppSpacing.md),AppTextField(controller:years,label:l.yearsExperience,keyboardType:TextInputType.number),const SizedBox(height:AppSpacing.lg),OutlinedButton.icon(onPressed:_locate,icon:const Icon(Icons.my_location_rounded),label:Text(lat==null?l.useCurrentLocation:'${l.location} ✓')),if(error!=null)Padding(padding:const EdgeInsets.only(top:AppSpacing.md),child:Text(error!,style:const TextStyle(color:AppColors.error))),const SizedBox(height:AppSpacing.xxl),PrimaryButton(label:l.saveProfile,isLoading:loading,isEnabled:!loading,onPressed:()=>_save(l))]))));}Future<void> _locate()async{final p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever){setState(()=>error=AppLocalizations.of(context)!.locationUnavailable);return;}final pos=await Geolocator.getCurrentPosition();setState((){lat=pos.latitude;lng=pos.longitude;error=null;});}Future<void> _pick(bool isFront)async{final f=await ImagePicker().pickImage(source:ImageSource.gallery);if(!mounted||f==null)return;setState(() { if (isFront) { front=f.path; } else { back=f.path; } });}
Future<void> _save(AppLocalizations l)async{final y=int.tryParse(years.text);if(name.text.trim().isEmpty||cnic.text.trim().isEmpty||area.text.trim().isEmpty||city.text.trim().isEmpty||lat==null||y==null||front==null||back==null){setState(()=>error=l.profileRequired);return;}setState(()=>loading=true);final user=ref.read(authStateProvider).valueOrNull!;await SaveProviderProfile(ref.read(profileRepositoryProvider)).call(user.id,ProviderProfileDraft(fullName:name.text.trim(),cnicNumber:cnic.text.trim(),area:area.text.trim(),city:city.text.trim(),latitude:lat!,longitude:lng!,yearsExperience:y,cnicFrontPath:front,cnicBackPath:back,photoPath:photo));ref.invalidate(profileStatusProvider);if(mounted)context.go(RouteNames.providerFeed);}}
